// conteudo: so o que esta no video oficial, nas imagens ou nas noticias ja publicadas no site. Sem numero em aberto.
// Dados base em espacos/dados.js; o painel sobrescreve textos e capa (espacosPaginas).
const S_BASE = JSON.parse(JSON.stringify(window.PNMT_ESPACOS_BASE || []));
const S = S_BASE.map(o => ({...o}));
const CAMPOS_EDITAVEIS = ['nome','tag','lead','txt','d','sec','sit','hero','capaFoto','capaVideo'];
function aplicarPainel(){
  let pag = null;
  try { pag = window.PNMT_ADMIN_DATA && window.PNMT_ADMIN_DATA.getData().espacosPaginas; } catch(e) {}
  S.forEach((s, i) => {
    const base = S_BASE[i];
    CAMPOS_EDITAVEIS.forEach(k => { if (k in base) s[k] = JSON.parse(JSON.stringify(base[k])); else delete s[k]; });
    const o = pag && pag[s.id];
    s._painel = o || null;
    if (!o) return;
    CAMPOS_EDITAVEIS.forEach(k => {
      const v = o[k];
      if (v == null) return;
      if (Array.isArray(v) ? v.length : String(v).trim() !== '') s[k] = JSON.parse(JSON.stringify(v));
    });
  });
}
aplicarPainel();
window.addEventListener('pnmt:content-updated', aplicarPainel);
// Textos editáveis do Onde estamos (padrão em content.js -> textosPadrao).
const escT = v => String(v == null ? '' : v).replace(/[&<>"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
function TX(k){
  let v = null;
  try { const t = window.PNMT_ADMIN_DATA && window.PNMT_ADMIN_DATA.getData().textos; v = t && t[k]; } catch(e) {}
  if (v == null || String(v).trim() === '') { const d = window.PNMT_CONTENT && window.PNMT_CONTENT.textosPadrao && window.PNMT_CONTENT.textosPadrao[k]; v = d ? d.valor : ''; }
  return escT(v);
}
