function tiraVideo(){ const xh = $('#xh'); if(!xh) return; clearTimeout(xh._vt); xh.classList.remove('vid'); xh.querySelectorAll('.xvi').forEach(l => l.remove()); xh.querySelectorAll('.xv').forEach(v => { v.classList.remove('on'); v.pause(); setTimeout(() => v.remove(), 700); }); }
