// Abertura: o take real (DJI_0039, tratado) toca uma vez e se funde na imagem ilustrativa com os pontos.
// Abertura: o take real (DJI_0039, tratado) toca uma vez com os pontos presos a imagem; no fim os pontos deslizam
// para o lugar deles na imagem ilustrativa, que fica parada. Os pontos ja sao clicaveis durante o video.
function intro(){
  const v = $('#xintro'), xh = $('#xh'); if(!v) return;
  const pula = matchMedia('(prefers-reduced-motion: reduce)').matches || (navigator.connection && navigator.connection.saveData);
  if(pula){ v.remove(); return; }
  xh.classList.add('xabre'); let feito = false;
  const pins = S.filter(s => s.px != null).map(s => [s, $(`.xpin[data-id="${s.id}"]`)]).filter(([, p]) => p);
  pins.forEach(([s, p]) => { if(!TRK[s.id]) p.classList.add('semv'); });
  // o video (16:9) cobre a camada da imagem (2:1): sobra 6,25% em cima e embaixo
  const poe = () => { const i = Math.max(0, Math.round(v.currentTime * TRK_FPS));
    pins.forEach(([s, p]) => { const a = TRK[s.id]; if(!a || a[i*2] == null) return; p.style.left = a[i*2] + '%'; p.style.top = (a[i*2+1] * 1.125 - 6.25) + '%'; }); };
  const roda = () => { if(feito || !v.isConnected) return; poe(); if(v.requestVideoFrameCallback) v.requestVideoFrameCallback(roda); else requestAnimationFrame(roda); };
  const fim = () => { if(feito) return; feito = true; v.pause(); xh.classList.add('morph'); xh.classList.remove('xabre');
    pins.forEach(([s, p]) => { p.classList.remove('semv'); p.style.left = s.px + '%'; p.style.top = s.py + '%'; });
    v.classList.add('off'); setTimeout(() => { v.remove(); xh.classList.remove('morph'); }, 1700); };
  xh._fim = fim; poe(); roda();
  v.addEventListener('timeupdate', () => { if(v.currentTime >= 7.5) fim(); });
  v.addEventListener('ended', fim); v.addEventListener('error', fim);
  const r = v.play(); if(r && r.catch) r.catch(fim);
  setTimeout(fim, 12000);
}
function solta(){ tiraVideo(); const xl = $('#xl'); if(!xl) return; xl.style.transform = ''; xl.style.setProperty('--s', 1); $('#xh').classList.remove('focus'); $$('.xpin').forEach(p => p.classList.remove('on')); }
