    let lbF = [], lbK = 0, lbN = '';
function abrir(f,k,n){ lbF = f; lbK = k; lbN = n; $('#lb').hidden = false; mostrar(); }
function mostrar(){ $('#lbi').src = lbF[lbK][0]; $('#lbc').textContent = `${lbF[lbK][1] || lbN} · ${lbK+1} de ${lbF.length}`; }
$('#lbx').onclick = () => $('#lb').hidden = true;
$('#lbl').onclick = () => { lbK = (lbK-1+lbF.length)%lbF.length; mostrar(); };
$('#lbr').onclick = () => { lbK = (lbK+1)%lbF.length; mostrar(); };
this._key = ( e => { if($('#lb').hidden) return; if(e.key==='Escape') $('#lbx').click(); if(e.key==='ArrowLeft') $('#lbl').click(); if(e.key==='ArrowRight') $('#lbr').click(); }); document.addEventListener('keydown', this._key);

    const id = this.dataset.view;
